// openapiYAML + openapiJSON are the committed, code-generated spec bytes
// (regenerated by `make web-build` → `swag init`, Task 14). Embedding the
// committed bytes — not generating at runtime — means the Go build gate serves
// the contract with swag absent from the host (INV-spec-is-static). The embed
// paths are relative to this file (internal/web/), so they reach into api/.
//
//go:embed api/openapi.yaml
var openapiYAML []byte

//go:embed api/openapi.json
